#include <stdio.h>

void oTamanhoReal(void) {
    int v[] = {3, 1, 4, 1, 5};
    int gaveta = sizeof v[0];
    int lista = sizeof v;
    int n = lista / gaveta;

    printf("uma gaveta ocupa %d bytes\n", gaveta);
    printf("a lista ocupa %d bytes\n", lista);
    printf("a lista tem %d gavetas\n", n);

    for (int i = 0; i < n; i++) {
        printf("%d\n", v[i]);
    }
}
